  `author_alias` varchar(50) DEFAULT NULL COMMENT 'AI署名(如"AI小文")',
  `model` varchar(64) DEFAULT NULL COMMENT '使用的AI模型',
  `prompt` text COMMENT '生成用prompt(可复现)',
