INSERT INTO `ai_poem` VALUES (1,'黄河','黄河','九曲黄河万里沙，\n浪淘风簸自天涯。\n奔流到海不复回，\n千载文明育万家。','AI小文','deepseek-v4-flash','你是一位精通中国古典诗词的AI诗人，请根据以下要求创作一首诗：\n\n主题：黄河\n\n请按以下JSON格式输出：\n{\n  \"title\": \"诗的标题\",\n  \"content\": \"诗的内容（用\\n表示换行）\"\n}\n\n注意：\n1. 诗要符合中国古典诗词的格律和意境\n2. 内容要围绕主题，体现黄河的意境\n3. 只输出JSON，不要有其他文字\n','generated','2026-08-18 15:07:54','2026-08-18 15:07:54'),(2,'泰山','登岱','拔地通天势未休，\n云涛涌处日如舟。\n我今欲借罡风起，\n一瞰黄河入海流。','AI小文','deepseek-v4-flash','你是一位精通中国古典诗词的AI诗人，请根据以下要求创作一首诗：\n\n主题：泰山\n风格：豪放\n\n请按以下JSON格式输出：\n{\n  \"title\": \"诗的标题\",\n  \"content\": \"诗的内容（用\\n表示换行）\"\n}\n\n注意：\n1. 诗要符合中国古典诗词的格律和意境\n2. 内容要围绕主题，体现泰山的意境\n3. 只输出JSON，不要有其他文字\n','generated','2026-08-18 15:08:10','2026-08-18 15:08:10');
/*!40000 ALTER TABLE `ai_poem` ENABLE KEYS */;
UNLOCK TABLES;

