CREATE TABLE `craft_detail` (
  `item_id` bigint NOT NULL COMMENT '文化条目ID',
  `craft_category` varchar(50) DEFAULT NULL COMMENT '工艺类别: 雕刻/编织/刺绣/陶瓷等',
  `materials` text COMMENT '所需材料',
