INSERT INTO `craft_detail` VALUES (33,'传统技艺','竹子、纸/绢、颜料、丝线、浆糊','削刀、剪刀、画笔、尺子、钳子','1. 选竹：选用毛竹或紫竹，要求弹性好、韧性足\n2. 削竹：将竹子削成所需粗细的竹条\n3. 扎架：用线绑扎成风筝骨架\n4. 糊面：用纸或绢糊在骨架上\n5. 绘画：在风筝面上绘制图案\n6. 提线：安装提线，调整平衡','潍坊风筝代表性传承人包括张效东、杨红卫等','龙头蜈蚣、蝴蝶风筝、金鱼风筝、仙鹤风筝',4,'潍坊世界风筝博物馆、潍坊风筝制作技艺传习所'),(34,'传统技艺','高岭土、长石、石英、滑石、陶土','拉坯机、窑炉、修坯刀、施釉设备','1. 选料：精选优质陶土和釉料\n2. 制泥：将原料粉碎、淘洗、沉淀、练泥\n3. 成型：拉坯、注浆或手捏成型\n4. 干燥：自然晾干或烘干\n5. 施釉：浸釉、浇釉或喷釉\n6. 烧成：在1200-1300℃高温下烧制','淄博陶瓷代表性传承人包括陈贻谟、冯乃藻等','雨点釉茶具、茶叶末釉花瓶、淄博刻瓷',5,'中国陶瓷馆、淄博陶瓷琉璃博物馆'),(35,'传统技艺','葫芦（亚腰葫芦、瓢葫芦等）、颜料','刻刀、电烙铁、砂纸、画笔','1. 选葫芦：选择形状规整、表面光滑的葫芦\n2. 去皮：刮去葫芦外层青皮\n3. 设计：在葫芦上画出图案\n4. 雕刻：用刻刀雕刻图案\n5. 着色：根据需要上色\n6. 上光：涂保护漆','东昌葫芦雕刻代表性传承人包括李玉成、王树峰等','葫芦烙画、葫芦雕刻、葫芦彩绘',3,'东昌葫芦雕刻传习所、聊城葫芦博物馆'),(36,'传统美术','丝线、棉线、绸缎、棉布、绣花针','绣花针、绣花绷子、剪刀、顶针','1. 设计图案：绘制绣稿\n2. 上绷：将布料绷在绣花绷子上\n3. 配线：选择合适颜色的丝线\n4. 刺绣：按照图案进行刺绣\n5. 整理：修剪线头，整理绣品','鲁绣代表性传承人包括王兴兰、李秀云等','鲁绣屏风、鲁绣服饰、鲁绣日用品',4,'济南鲁绣传习所、山东省博物馆'),(37,'传统美术','梨木板、宣纸、颜料、墨汁','刻刀、木槌、印刷台、棕擦','1. 画稿：绘制年画图案\n2. 刻版：将图案刻在梨木板上\n3. 印刷：用墨汁印刷轮廓\n4. 彩绘：手工上色\n5. 晾干：自然晾干','杨家埠年画代表性传承人包括杨洛书、杨福源等','门神年画、灶王年画、财神年画、戏曲年画',4,'杨家埠木版年画博物馆、潍坊年画传习所'),(38,'传统戏剧','牛皮、驴皮、颜料、丝线','刻刀、针、画笔、模具','1. 选皮：选择优质牛皮或驴皮\n2. 泡制：将皮子泡软、刮薄\n3. 画样：在皮子上画出人物图样\n4. 雕刻：用刻刀雕刻人物\n5. 着色：给人物上色\n6. 组装：用丝线连接各部件','济南皮影戏代表性传承人包括李兴堂、王振华等','《西游记》皮影、《三国演义》皮影、传统戏曲皮影',4,'济南皮影戏传习所、济南非遗展示馆'),(77,'面塑','小麦面粉、糯米粉（江米粉）、蜂蜜、食用色素、防腐剂','捏塑刀（竹刀/牛角刀）、剪刀、梳子、模具、垫板','1. 和面：面粉加糯米粉、蜂蜜等蒸熟揉匀\n2. 调色：分块调入各色颜料\n3. 捏塑：按头、身、四肢顺序捏出造型\n4. 妆饰：用刀具压出衣纹、五官\n5. 晾干：自然阴干定型','曹州面人传承群体（曹县江米人艺人群，代表性传承人姓名待考）','面塑牡丹、戏曲人物面人、十二生肖面人',3,'菏泽非遗工坊体验、曹州面人传习所/研学课堂'),(78,'织造','纯棉纱线、彩色棉纱、经线、纬线','木织机、梭子、综、筘、纺车、染缸','1. 纺线：纺车纺出棉纱\n2. 染线：染色备用\n3. 经线：按纹样设计排经\n4. 上机：穿综过筘\n5. 织造：踩踏板投梭织布\n6. 整理：下机、缩水、修边','鲁锦织造传承群体（鄄城、郓城织女群体）','鲁锦床单、鲁锦服饰、鲁锦壁挂、八宝纹鲁锦',3,'菏泽鲁锦文化展示体验中心、非遗工坊研学'),(79,'雕刻','楷木（黄连木）、蜡、清漆','刻刀（平刀、圆刀、三角刀）、木槌、锉刀、砂纸','1. 选料：选用孔林楷木，去湿晾干\n2. 画样：在木坯上勾画图样\n3. 粗雕：凿出整体轮廓\n4. 细雕：精刻眉眼衣纹\n5. 打磨：砂纸抛光\n6. 上蜡：涂蜡或清漆养护','曲阜楷木雕刻传承群体（曲阜艺人群，代表性传承人姓名待考）','楷木孔子像、楷木如意、楷木手杖、楷木镇纸',4,'曲阜非遗传习所、孔府/孔庙研学体验'),(80,'雕刻','青石（石灰岩）、花岗岩、汉白玉','錾子、锤子、凿子、磨光机、切割机','1. 选石：挑选质地致密的青石/花岗岩\n2. 设计：绘制图样或打样\n3. 开坯：切割石材粗坯\n4. 粗雕：錾凿出大形\n5. 细雕：精刻细部纹饰\n6. 磨光：打磨抛光','嘉祥石雕艺人群体（武氏祠石刻技艺传承脉络）','石麒麟、石狮子、汉画像石拓片、人物石雕',5,'嘉祥石雕文化产业园、嘉祥石雕厂见习'),(81,'雕刻','泰山墨玉、泰山碧玉、翠斑玉、金刚砂','玉石切割机、雕磨机、钻头、抛光轮、刻刀','1. 选料：鉴别玉石质地与色泽\n2. 设计：依形构思图样\n3. 切割：切出坯料\n4. 雕琢：水磨雕刻造型\n5. 抛光：打磨上光\n6. 配饰：穿绳配座成器','泰山玉雕传承群体（泰山张氏玉雕等老字号艺人群）','泰山平安玉佩、泰山风景玉雕、墨玉茶具、玉印章',4,'泰安市文化馆非遗体验活动、玉石雕刻工坊学徒'),(82,'雕刻','桃木（肥城桃木）、清漆、蜡','刻刀、木工锯、刨、砂纸、电磨','1. 选材：取老桃木晾干\n2. 开料：锯出坯形\n3. 粗雕：凿出轮廓\n4. 精雕：刻出纹饰\n5. 打磨：抛光表面\n6. 上漆：涂清漆或打蜡','王来新（\"桃木王\"）等肥城桃木雕刻艺人群','桃木剑、桃木如意、桃符、桃木生肖摆件',3,'肥城桃木旅游商品博物馆、桃木雕刻工坊体验'),(83,'制陶','黄河细泥（淤积土）、水、釉料（彩陶用）','拉坯机、转盘、修坯刀、刻刀、压光板、窑炉','1. 取泥：采黄河细泥淘洗沉淀\n2. 练泥：揉练排除气泡\n3. 拉坯：转盘上拉出器形\n4. 修坯：修整器壁\n5. 雕刻压光：刻花并压光\n6. 烧制：渗碳还原烧成黑陶','梁丽霞（德州梁子黑陶文化有限公司负责人）及黑陶艺人群体（省级传承人名单待考）','黑陶瓶、黑陶茶具、硬刻陶花觚、镂空黑陶',5,'梁子黑陶文化园体验、德州学院黑陶文化产业学院'),(84,'制陶','黄河澄浆泥、细沙','拉坯机/转轮、刮板、刻刀、模具、窑炉','1. 澄泥：黄河泥加水沉淀取细泥\n2. 练泥：揉练至细腻均匀\n3. 制坯：拉坯或模制罐身\n4. 修坯：刮光内外壁\n5. 刻花：刻吉祥纹样\n6. 烧制：低温烧成','宁津蟋蟀罐制作艺人群体（代表性传承人姓名待考）','澄浆泥蟋蟀罐、雕花蟋蟀罐、斗盆',3,'宁津非遗工坊体验、蟋蟀文化市场研学'),(85,'泥塑','黄河胶泥、麦秸、颜料（广告色/矿物色）','捏塑刀、竹签、模具、画笔、晾架','1. 取泥：采黄河胶泥掺麦秸揉练\n2. 塑形：手捏或模具翻制坯体\n3. 晾干：阴干防裂\n4. 打磨：修整表面\n5. 彩绘：白粉打底后上色','惠民河南张村泥塑艺人群（火把李庙会传承脉络）','泥娃娃（不倒翁）、戏曲人物泥塑、十二生肖泥塑',2,'惠民火把李庙会、河南张村泥塑工坊体验'),(86,'编织','柳条、蒲草、玉米皮、棉绳','剪刀、锥子、模具、压条器','1. 备料：柳条去皮晾干、蒲草理顺\n2. 浸泡：入水浸泡增加柔韧性\n3. 起底：编出器物底部\n4. 编身：自下而上编出器壁\n5. 收口：编沿收边\n6. 修饰：修剪毛刺、加配件','博兴草柳编传承群体（湾头、锦秋一带编织艺人）','柳编提篮、蒲草坐垫、草编工艺品、柳编箱包',3,'博兴草柳编一条街体验、非遗工坊研学'),(87,'制笔','狼毫、羊毫、紫毫等兽毛、竹管/木管、胶','梳笔梳、刀、针、缠线、胶锅','1. 选毫：挑选兽毛分类\n2. 脱脂：石灰水浸泡去脂\n3. 梳理：梳齐毫毛\n4. 扎毫：捆扎笔头\n5. 装管：笔头装入笔杆\n6. 修笔：修圆笔锋、定型','郭明昌（省级非遗齐笔制作技艺第五代传承人）、朱长春等','齐笔狼毫、齐笔羊毫、书法套装笔',4,'广饶齐笔非遗展览/工作室体验、齐笔工坊研学'),(88,'贴画','芦苇秆、芦苇花、胶、相框','剪刀、烙铁（电烙笔）、镊子、压平器、浆糊','1. 选料：采黄河口芦苇\n2. 剖秆压平：剖开秆皮压展\n3. 剪贴：剪出形象拼贴\n4. 烙烫：烙笔烫出明暗层次\n5. 装裱：入框成画','河口区芦苇画传承群体（代表性传承人姓名待考）','黄河湿地风光画、芦苇烙画生肖摆件',3,'东营市文化馆非遗传习课程、河口区文化馆体验');
/*!40000 ALTER TABLE `craft_detail` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `cultural_item`
--

DROP TABLE IF EXISTS `cultural_item`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `cultural_item` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `category` varchar(20) NOT NULL COMMENT 'festival节庆/craft非遗/literature民间文学/food_opera饮食戏曲',
  `title` varchar(200) NOT NULL COMMENT '名称',
  `summary` varchar(500) DEFAULT NULL COMMENT '一句话简介（卡片用）',
  `content` text COMMENT '详细介绍正文',
  `region` varchar(50) DEFAULT NULL COMMENT '所属区域（沿黄九市，NULL=全域性内容）',
  `image_url` varchar(500) DEFAULT NULL COMMENT '实景图',
  `image_anime_url` varchar(500) DEFAULT NULL COMMENT '水墨风图',
  `tags` json DEFAULT NULL COMMENT '标签数组',
  `sort_order` int DEFAULT '0' COMMENT '排序权重',
  `status` varchar(20) DEFAULT 'draft' COMMENT 'draft草稿/published已发布',
  `source` varchar(20) DEFAULT 'manual' COMMENT 'ai生成/manual人工',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `related_poets` json DEFAULT NULL COMMENT '关联诗人ID数组',
  `related_spots` json DEFAULT NULL COMMENT '关联景点ID数组',
  `related_poems` json DEFAULT NULL COMMENT '关联诗词ID数组',
  `view_count` int DEFAULT '0' COMMENT '浏览次数',
  `like_count` int DEFAULT '0' COMMENT '点赞次数',
  PRIMARY KEY (`id`),
  KEY `idx_category_status` (`category`,`status`),
  KEY `idx_region` (`region`),
  KEY `idx_cultural_item_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=98 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='文化条目公共表';
/*!40101 SET character_set_client = @saved_cs_client */;

