/*!40000 ALTER TABLE `cultural_item` DISABLE KEYS */;
INSERT INTO `cultural_item` VALUES (33,'craft','潍坊风筝制作技艺','国家级非物质文化遗产，以造型优美、扎工精巧、绘画细腻著称。','潍坊风筝制作技艺是国家级非物质文化遗产。潍坊风筝以其优美的造型、精巧的扎工、细腻的绘画和浓郁的民间气息而闻名于世。传统潍坊风筝用竹子扎骨架，用纸或绢糊面，再施以彩绘。制作工艺分为扎、糊、绘、放四个主要环节，每一步都有严格的技术要求。潍坊风筝种类繁多，有龙头蜈蚣、蝴蝶、金鱼、仙鹤等数百种造型。','潍坊',NULL,NULL,'[\"国家级非遗\", \"潍坊\", \"传统技艺\"]',0,'published','ai','2026-08-15 09:16:35','2026-08-15 09:16:35',NULL,NULL,NULL,0,0),(34,'craft','淄博陶瓷烧制技艺','国家级非物质文化遗产，以雨点釉、茶叶末釉等名贵釉色著称。','淄博陶瓷烧制技艺是国家级非物质文化遗产。淄博是中国陶瓷的重要发源地之一，有着8000多年的制陶历史。淄博陶瓷以雨点釉、茶叶末釉等名贵釉色著称，其中雨点釉被誉为\'中国之奇、天下之宝\'。淄博陶瓷制作工艺复杂，需要经过选料、制泥、成型、干燥、施釉、烧成等多道工序。','淄博',NULL,NULL,'[\"国家级非遗\", \"淄博\", \"传统技艺\"]',0,'published','ai','2026-08-15 09:16:35','2026-08-15 09:16:35',NULL,NULL,NULL,0,0),(35,'craft','东昌葫芦雕刻','省级非物质文化遗产，在葫芦上雕刻各种图案和文字的传统技艺。','东昌葫芦雕刻是山东省省级非物质文化遗产。聊城东昌府区是著名的葫芦之乡，葫芦雕刻技艺历史悠久。艺人们在葫芦上雕刻各种图案和文字，题材包括花鸟鱼虫、人物故事、山水风景等。雕刻技法有浮雕、透雕、线刻等多种，作品精美绝伦，具有很高的艺术价值。','聊城',NULL,NULL,'[\"省级非遗\", \"聊城\", \"传统技艺\"]',0,'published','ai','2026-08-15 09:16:35','2026-08-15 09:16:35',NULL,NULL,NULL,0,0),(36,'craft','鲁绣','国家级非物质文化遗产，山东地区的传统刺绣技艺。','鲁绣是国家级非物质文化遗产，是山东地区的传统刺绣技艺。鲁绣历史悠久，早在春秋时期就已经出现。鲁绣以丝线、棉线为材料，在绸缎、棉布上绣制各种图案。鲁绣针法丰富，有齐针、套针、抢针、乱针等数十种。题材以花鸟、山水、人物为主，色彩鲜明，构图饱满，具有浓郁的地方特色。','济南',NULL,NULL,'[\"国家级非遗\", \"济南\", \"传统美术\"]',0,'published','ai','2026-08-15 09:16:35','2026-08-15 09:16:35',NULL,NULL,NULL,0,0),(37,'craft','杨家埠木版年画','国家级非物质文化遗产，与天津杨柳青、苏州桃花坞年画齐名。','杨家埠木版年画是国家级非物质文化遗产，与天津杨柳青、苏州桃花坞年画并称中国三大木版年画。杨家埠年画起源于明代，至今已有500多年历史。年画内容以门神、灶王、财神等民俗题材为主，也有历史故事、戏曲人物等。制作工艺包括画稿、刻版、印刷、彩绘等步骤。','潍坊',NULL,NULL,'[\"国家级非遗\", \"潍坊\", \"传统美术\"]',0,'published','ai','2026-08-15 09:16:35','2026-08-15 09:16:35',NULL,NULL,NULL,0,0),(38,'craft','济南皮影戏','省级非物质文化遗产，用兽皮雕镂成人物剪影进行表演的传统艺术。','济南皮影戏是山东省省级非物质文化遗产。皮影戏是用兽皮雕镂成人物剪影，借助灯光在幕布后表演的传统艺术形式。济南皮影戏历史悠久，清代就已经盛行。皮影人物造型精美，色彩鲜艳，表演时配以唱词和乐器伴奏，深受群众喜爱。','济南',NULL,NULL,'[\"省级非遗\", \"济南\", \"传统戏剧\"]',0,'published','ai','2026-08-15 09:16:35','2026-08-15 09:16:35',NULL,NULL,NULL,0,0),(39,'literature','孟姜女传说','中国四大民间传说之一，讲述孟姜女哭倒长城的故事。','孟姜女传说是中国四大民间传说之一。相传秦朝时期，孟姜女的丈夫范喜良被征去修长城，多年未归。孟姜女千里寻夫，得知丈夫已死，悲痛欲绝，哭了三天三夜，竟把长城哭倒了一段。这个传说反映了古代劳动人民对暴政的控诉和对爱情忠贞的赞美。山东泰安、淄博等地都有孟姜女传说的流传版本。','泰安',NULL,NULL,'[\"四大传说\", \"泰安\", \"爱情传说\"]',0,'published','ai','2026-08-15 09:16:35','2026-08-15 09:16:35',NULL,NULL,NULL,0,0),(40,'literature','梁祝传说','中国四大民间传说之一，讲述梁山伯与祝英台的爱情故事。','梁祝传说是中国四大民间传说之一。相传东晋时期，祝英台女扮男装外出求学，与梁山伯同窗三年。梁山伯不知祝英台是女子，待得知真相后，祝英台已被许配他人。梁山伯相思成疾而死，祝英台出嫁途中祭拜梁山伯墓，墓裂而入，双双化蝶。山东济宁等地有梁祝传说的流传版本。','济宁',NULL,NULL,'[\"四大传说\", \"济宁\", \"爱情传说\"]',0,'published','ai','2026-08-15 09:16:35','2026-08-15 09:16:35',NULL,NULL,NULL,0,0),(41,'literature','泰山传说','关于泰山的神话传说，包括泰山老奶奶、碧霞元君等。','泰山传说是关于泰山的神话传说。泰山被誉为五岳之首，自古就是帝王封禅之地。传说泰山老奶奶（碧霞元君）是泰山的主神，掌管人间生死福祸。泰山还有许多著名传说，如泰山石敢当、泰山挑夫等。这些传说反映了古代人民对自然的敬畏和对美好生活的向往。','泰安',NULL,NULL,'[\"泰山\", \"泰安\", \"神话传说\"]',0,'published','ai','2026-08-15 09:16:35','2026-08-15 09:16:35',NULL,NULL,NULL,0,0),(42,'literature','运河传说','关于京杭大运河的民间传说，反映运河沿岸人民的生活。','运河流传说是关于京杭大运河的民间传说。聊城是运河沿岸的重要城市，流传着许多与运河有关的传说。这些传说反映了运河沿岸人民的生活、劳动和爱情，展现了运河文化的丰富内涵。著名的传说包括运河龙王、运河纤夫、运河商帮等。','聊城',NULL,NULL,'[\"运河\", \"聊城\", \"生活传说\"]',0,'published','ai','2026-08-15 09:16:35','2026-08-15 09:16:35',NULL,NULL,NULL,0,0),(43,'literature','黄河号子','黄河沿岸劳动人民在劳动中创作的民歌，节奏铿锵有力。','黄河号子是黄河沿岸劳动人民在劳动中创作的民歌。在黄河航运、筑堤、抢险等劳动中，人们为了统一节奏、鼓舞士气，创作了各种号子。黄河号子节奏铿锵有力，歌词朴实生动，反映了黄河人民的勤劳勇敢和乐观精神。著名的有黄河船工号子、黄河夯歌等。','东营',NULL,NULL,'[\"黄河\", \"东营\", \"劳动号子\"]',0,'published','ai','2026-08-15 09:16:35','2026-08-15 09:16:35',NULL,NULL,NULL,0,0),(44,'literature','孔融让梨','孔子后裔孔融幼时让梨的故事，体现礼让美德。','孔融让梨是孔子后裔孔融幼时的故事。孔融四岁时，与兄弟们一起吃梨，他每次都拿最小的。大人问他为什么，他说：\'我年纪小，应该吃小的，大的留给哥哥们。\'这个故事体现了中华民族礼让的传统美德，成为教育儿童的经典故事。孔融是孔子的二十世孙，山东曲阜人。','济宁',NULL,NULL,'[\"孔子\", \"济宁\", \"美德故事\"]',0,'published','ai','2026-08-15 09:16:35','2026-08-15 09:16:35',NULL,NULL,NULL,0,0),(45,'food_opera','鲁菜','中国八大菜系之首，以咸鲜为主，注重火候，讲究原汁原味。','鲁菜是中国八大菜系之首，也是历史最悠久、技法最丰富的菜系。鲁菜以咸鲜为主，注重火候，讲究原汁原味。鲁菜选料精细，刀工精湛，烹调方法多样，擅长爆、炒、烧、塌、焖等技法。鲁菜分为济南菜、胶东菜、孔府菜三大流派，各具特色。','济南',NULL,NULL,'[\"八大菜系\", \"济南\", \"传统美食\"]',0,'published','ai','2026-08-15 09:16:35','2026-08-15 09:16:35',NULL,NULL,NULL,0,0),(46,'food_opera','德州扒鸡','德州三宝之一，以五香脱骨、肉嫩味纯著称。','德州扒鸡是德州三宝之一，以五香脱骨、肉嫩味纯著称。德州扒鸡始于明代，至今已有300多年历史。制作工艺独特，需经过宰杀、整形、油炸、卤煮等多道工序。成品色泽金黄，肉质鲜嫩，骨酥肉烂，香气扑鼻。','德州',NULL,NULL,'[\"德州\", \"传统美食\", \"中华老字号\"]',0,'published','ai','2026-08-15 09:16:35','2026-08-15 09:16:35',NULL,NULL,NULL,0,0),(47,'food_opera','周村烧饼','淄博周村传统名点，以薄、香、酥、脆著称。','周村烧饼是淄博周村传统名点，以薄、香、酥、脆著称。周村烧饼起源于汉代，至今已有1800多年历史。制作工艺独特，需经过和面、揉剂、成型、烘烤等多道工序。成品薄如纸，酥如雪，香如兰，口感酥脆，回味无穷。','淄博',NULL,NULL,'[\"淄博\", \"传统美食\", \"中华老字号\"]',0,'published','ai','2026-08-15 09:16:35','2026-08-15 09:16:35',NULL,NULL,NULL,0,0),(48,'food_opera','煎饼卷大葱','山东传统主食，以杂粮煎饼卷大葱、蘸酱食用。','煎饼卷大葱是山东传统主食，以杂粮煎饼卷大葱、蘸酱食用。山东煎饼历史悠久，相传孟姜女哭长城时带的就是煎饼。煎饼以小米、玉米、高粱等杂粮为原料，摊制而成。食用时卷上大葱、蘸上酱料，简单美味，营养丰富。','临沂',NULL,NULL,'[\"临沂\", \"传统美食\", \"地方小吃\"]',0,'published','ai','2026-08-15 09:16:35','2026-08-15 09:16:35',NULL,NULL,NULL,0,0),(49,'food_opera','吕剧','山东省地方戏曲剧种，以优美动听的唱腔著称。','吕剧是山东省地方戏曲剧种，起源于东营广饶地区。吕剧以优美动听的唱腔著称，唱腔以\'四平腔\'为基本曲调，旋律优美，节奏明快。吕剧表演朴实自然，贴近生活，深受山东人民喜爱。代表剧目有《李二嫂改嫁》《姊妹易嫁》等。','东营',NULL,NULL,'[\"东营\", \"地方戏曲\", \"国家级非遗\"]',0,'published','ai','2026-08-15 09:16:35','2026-08-15 09:16:35',NULL,NULL,NULL,0,0),(50,'food_opera','山东快书','山东省传统曲艺形式，以节奏明快、语言幽默著称。','山东快书是山东省传统曲艺形式，以节奏明快、语言幽默著称。山东快书起源于清代，由民间说唱艺术发展而来。表演者手持竹板，边打边说，节奏明快，语言生动。代表曲目有《武松传》《鲁达除霸》等。','济南',NULL,NULL,'[\"济南\", \"传统曲艺\", \"国家级非遗\"]',0,'published','ai','2026-08-15 09:16:35','2026-08-15 09:16:35',NULL,NULL,NULL,0,0),(51,'food_opera','柳子戏','山东省地方戏曲剧种，以粗犷豪放的唱腔著称。','柳子戏是山东省地方戏曲剧种，以粗犷豪放的唱腔著称。柳子戏起源于明代，由民间小调发展而来。唱腔以\'柳子调\'为主，旋律高亢激昂，表演粗犷豪放。代表剧目有《白兔记》《金锁记》等。','菏泽',NULL,NULL,'[\"菏泽\", \"地方戏曲\", \"国家级非遗\"]',0,'published','ai','2026-08-15 09:16:36','2026-08-15 09:16:36',NULL,NULL,NULL,0,0),(52,'festival','菏泽国际牡丹文化旅游节（曹州牡丹花会）','以“曹州牡丹甲天下”为根基的年度花会盛事，赏花、演艺与经贸交融，为黄河流域山东段春季最具人气的节庆。','菏泽古称曹州，牡丹栽培历史逾千年（栽培上限年代待考），明清时已有“曹州牡丹甲于海内”之誉。1992年，菏泽举办首届国际牡丹花会，此后每年四月花开时节如期举行，今称菏泽国际牡丹文化旅游节，已历三十余届。节会以曹州牡丹园等万亩花海为核心，融赏花游园、文艺演出、书画笔会、非遗展示与经贸洽谈于一体，近年更以“非遗+牡丹”为特色，集中展演菏泽面塑、戏曲、剪纸等非遗项目。花会既是花乡民俗的活态展台，也是菏泽城市形象与牡丹产业走向全国的重要窗口。','菏泽',NULL,'/images/cultural/peony_festival.webp','[\"节庆\", \"牡丹\", \"花会\", \"菏泽\", \"非遗展演\"]',0,'published','manual','2026-08-15 11:01:42','2026-08-24 21:00:47',NULL,NULL,NULL,0,0),(53,'festival','曲阜祭孔大典','曲阜孔庙举行的国家级非遗祭祀盛典，纪念孔子诞辰，佾舞雅乐、礼乐庄严，为儒家文化标志性仪式。','祭孔之礼始于孔子卒后次年（公元前478年），历代相沿，至明清形成规制完备的“释奠礼”。祭孔大典已列入国家级非物质文化遗产名录（批次年份待考）。当代曲阜祭孔大典每年9月28日孔子诞辰日于孔庙大成殿前举行，依古礼行迎神、三献等仪程，佾舞雅乐、衣冠肃穆，并联动海内外文庙与孔学堂同步祭拜。大典既承“国之大事，在祀与戎”的礼乐传统，亦成为中华优秀传统文化当代传承与世界文明对话的标志性文化符号，彰显儒家“仁礼”精神。','济宁',NULL,'/images/cultural/confucius_ceremony.webp','[\"祭祀\", \"儒家\", \"非遗\", \"曲阜\", \"礼乐\"]',0,'published','manual','2026-08-15 11:01:42','2026-08-24 21:00:47',NULL,NULL,NULL,0,0),(54,'festival','泰山东岳庙会','国家级非遗泰山民俗盛会，以东岳大帝信仰为核，朝山进香、百戏云集，山上祀神、山下赶集。','泰山东岳庙会源于泰山崇拜与东岳大帝信仰，随唐宋以来碧霞元君信仰的盛行而兴，明清时臻于鼎盛，是泰山最具代表性的民俗活动，已列入国家级非物质文化遗产名录（庙会类，批次年份待考）。传统会期以农历三月二十八东岳大帝诞辰为中心，当代庙会多于四月中下旬启会，会期数日至半月。庙会期间，朝山进香、祈福还愿与民间百戏、商贸集市交融，杂技曲艺、糖画面塑、泰山剪纸等非遗技艺竞相展演，形成“山上祀神、山下赶集”的独特文化景观，是泰山信仰与市井生活的生动联结。','泰安',NULL,NULL,'[\"庙会\", \"非遗\", \"泰山\", \"信仰\", \"民俗\"]',0,'published','manual','2026-08-15 11:01:42','2026-08-15 11:01:42',NULL,NULL,NULL,0,0),(55,'festival','临清庙会（古运河庙会）','明清运河商埠遗风的正月庙会，社火锣鼓、商贸百戏云集，重现“古埠烟火”景象。','临清为明清京杭大运河漕运重镇，清代“临清庙会不一而足”：城隍庙正月、腊月及五月二十八有会，五龙宫三月三有会，碧霞宫九月初有会（见地方史研究）。庙会随商埠繁盛而兴，融祭祀、商贸、娱乐于一体，是运河城市民俗的典型样本。当代临清庙会多集中于春节期间举办，以“非遗过大年”“冬游临清”贺年会等形式呈现，社火巡游、驾鼓锣鼓、戏曲曲艺与非遗市集云集，重现“古埠烟火”景象。当代庙会的固定名称与会期逐年调整，具体场次待考。','聊城',NULL,NULL,'[\"庙会\", \"运河\", \"临清\", \"社火\", \"非遗\"]',0,'published','manual','2026-08-15 11:01:42','2026-08-15 11:01:42',NULL,NULL,NULL,0,0),(56,'festival','临清驾鼓（新春社火锣鼓）','国家级非遗锣鼓艺术，运河古埠社火中的雄浑鼓声，春节庙会常闻，屡登央视舞台。','临清驾鼓是流传于临清一带的民间锣鼓艺术，2021年以“锣鼓艺术（临清驾鼓）”列入第五批国家级非物质文化遗产代表性项目名录。相传其鼓声曾为古代将帅助阵扬威，又随京杭大运河商埠的庙会社火传承不息（具体形成年代待考）。驾鼓鼓点雄壮、队列齐整，多人同击大鼓、铙钹相和，气势撼人，多于春节、庙会及重大庆典中展演，屡登央视及省市级节庆舞台，是临清乃至聊城最具辨识度的民俗声音符号。','聊城',NULL,NULL,'[\"非遗\", \"锣鼓\", \"社火\", \"临清\", \"民俗\"]',0,'published','manual','2026-08-15 11:01:42','2026-08-15 11:01:42',NULL,NULL,NULL,0,0),(57,'festival','趵突泉迎春花灯会','“海右第一灯会”，泉城新春赏灯盛事，花灯映泉、流光溢彩，年味绵延半个多世纪。','趵突泉迎春花灯会自1965年起办，已延续半个多世纪，被媒体誉为“海右第一灯会”。灯会依托趵突泉“泉涌灯明”的独特景致，于每年春节期间（腊月下旬至正月十五前后）在趵突泉公园举办，花灯依水而设、流光溢彩，融传统扎灯技艺与当代声光电于一体。灯会期间游人如织，猜灯谜、观民俗演出、品泉城年味相映成趣，是济南最具代表性的新春民俗节庆，也是北方城市灯会文化的经典样本。','济南',NULL,NULL,'[\"灯会\", \"春节\", \"济南\", \"花灯\", \"民俗\"]',0,'published','manual','2026-08-15 11:01:42','2026-08-15 11:01:42',NULL,NULL,NULL,0,0),(58,'festival','千佛山重阳山会（千佛山庙会）','延续七百余年的重阳登高庙会，登高赏菊、市集百戏，为泉城秋日标志性民俗盛景。','千佛山山会源于重阳登高古俗与庙会传统，据媒体报道已延续七百余年。每年农历九月初九重阳节前后，济南人登千佛山望远怀亲、赏菊祈福，山道两侧摊贩云集，杂技曲艺、糖画面塑、风味小吃纷呈，形成“重阳山会”盛景。山会既有敬老孝亲的文化内涵，亦承载泉城市民的秋日休闲记忆，与趵突泉迎春花灯会遥相呼应，一春一秋，构成济南岁时民俗的两大标志性节会。','济南',NULL,NULL,'[\"庙会\", \"重阳\", \"济南\", \"登高\", \"民俗\"]',0,'published','manual','2026-08-15 11:01:42','2026-08-15 11:01:42',NULL,NULL,NULL,0,0),(59,'festival','中国乐陵金丝小枣文化旅游节','金丝小枣之乡乐陵的年度枣文化盛会，枣熟时节采摘品鉴，枣乡民俗与产业文旅交融。','乐陵地处鲁北，为金丝小枣之乡，小枣栽培历史悠久，所产小枣“金丝万缕、香甜酥脆”，久负盛名。中国乐陵金丝小枣文化旅游节自1989年（据第32届于2020年举办推算）起每年9月枣熟时节举行，已历三十余届。节会以万亩枣林为舞台，融采摘体验、枣乡民俗展演、红枣品鉴与产业博览、文旅消费于一体，近年更与红枣健康食品产业博览会联动。节会是德州最具代表性的县域节庆，也是黄河流域枣文化与乡村振兴结合的生动样本。','德州',NULL,NULL,'[\"节庆\", \"枣文化\", \"乐陵\", \"德州\", \"产业文旅\"]',0,'published','manual','2026-08-15 11:01:42','2026-08-15 11:01:42',NULL,NULL,NULL,0,0),(60,'festival','宁津蟋蟀文化节（暨杂技古会）','蟋蟀之乡宁津的秋日民俗盛会，斗蟋观战、蟋蟀交易与杂技古会同台，非遗民俗新名片。','宁津素有“蟋蟀之乡”“杂技之乡”之誉，斗蟋风俗流传已久，宁津斗蟋已列入非遗保护名录（级别待考）。宁津蟋蟀文化节创办于2010年代（首届年份待考），已历十届（第十届于2024年举办），多在秋季斗蟋时节举行。节会期间斗蟋观战、蟋蟀交易与促消费活动并举；2024年首届“杂技古会”同期亮相，重现古会市集百戏景象，2026年又推出“杂技蟋蟀谷”艺术美食嘉年华。节会将蟋蟀民俗、杂技传统与文旅消费相融，是德州特色民俗节庆的新名片（会期逐年浮动，待考）。','德州',NULL,NULL,'[\"节庆\", \"斗蟋\", \"杂技\", \"宁津\", \"民俗\"]',0,'published','manual','2026-08-15 11:01:42','2026-08-15 11:01:42',NULL,NULL,NULL,0,0),(61,'festival','齐文化节（临淄）','齐国故都临淄的年度文化盛典，祭齐祖、展蹴鞠，弘扬泱泱齐风，黄河流域文化底蕴深厚的城市节庆。','淄博临淄为齐国故都，齐文化节自2004年起每年9月举行（第二十二届于2025年9月举办），是弘扬齐文化、展示故都风采的标志性节庆。节会以“泱泱齐风”为主题，设开幕式暨文艺演出、齐文化学术研讨、蹴鞠展演与体验（临淄为世界足球起源地，蹴鞠为国家级非遗）、非遗与文创市集等活动，并带动文旅经贸洽谈。齐文化节使“春秋五霸之首、战国七雄之一”的齐国历史文化走进当代，是黄河流域山东段最具文化底蕴的城市节庆之一。','淄博',NULL,NULL,'[\"节庆\", \"齐文化\", \"临淄\", \"蹴鞠\", \"文化节\"]',0,'published','manual','2026-08-15 11:01:42','2026-08-15 11:01:42',NULL,NULL,NULL,0,0),(62,'festival','淄博国际聊斋文化旅游节（聊斋文化节）','蒲松龄故里淄川的聊斋文化嘉年华，五一假期体验志怪奇幻，民俗活化与文旅融合的典型。','淄博国际聊斋文化旅游节创办于2002年（当年“五一”假期首办，2003年发布“国际”版本举办消息），在《聊斋志异》作者蒲松龄故里淄川区蒲家庄一带举行，多以“五一”假期为节期。节会以聊斋文化为魂，融聊斋园景区游览、情景剧与奇幻演艺、民俗市集、非遗展示于一体，近年以“聊斋文化节”“奇幻嘉年华”等名目持续举办（如2025年“五一”开幕的聊斋文化节）。节会将志怪文学的想象力转化为可游可感的文旅体验，是淄博文旅融合与民俗活化利用的典型代表。','淄博',NULL,NULL,'[\"节庆\", \"聊斋\", \"淄川\", \"蒲松龄\", \"文旅\"]',0,'published','manual','2026-08-15 11:01:42','2026-08-15 11:01:42',NULL,NULL,NULL,0,0),(63,'festival','惠民胡集书会','“中国民间艺术活化石”，正月十二开锣的八百年曲艺大集，一日能看千台戏、四天可读万卷书。','胡集书会于每年农历正月十二至十六前后在滨州市惠民县胡集镇举行，据称已有八百年传承历史（起源年代待考），已列入国家级非物质文化遗产名录（曲艺类，批次年份待考），被誉为“中国民间艺术活化石”。届时全国各地曲艺艺人云集胡集，鼓书、琴书、评书、快板等竞相献艺，素有“一日能看千台戏，四天可读万卷书”之誉，堪称中国北方民间曲艺的活态博物馆。当代书会兼设曲艺擂台、非遗市集与文旅活动，2026年书会于2月28日至3月4日举办，盛况再续。','滨州',NULL,NULL,'[\"曲艺\", \"非遗\", \"书会\", \"滨州\", \"民俗\"]',0,'published','manual','2026-08-15 11:01:42','2026-08-15 11:01:42',NULL,NULL,NULL,0,0),(64,'festival','黄河口开渔节','黄蓝交汇处渔港的开海盛会，千帆竞发、祭海祈福，开海第一鲜热闹登场。','每年9月1日黄渤海伏季休渔期结束，东营沿海渔港迎来开渔时节。2017年，垦利区红光渔港举办首届开渔节，此后延续为一年一度的渔港节庆（节名与会期逐年略有调整）。开渔节上，锣鼓齐鸣、千帆竞发，渔民以祭海祈福仪式祈愿鱼虾满仓、平安归来（祭海仪式细节待考）；开海首捕归航后，渔港码头随即举办海鲜美食节，梭子蟹、大虾、梭鱼等“开海第一鲜”供市民游客尝鲜。开渔节既承渔民敬海传统，也见证黄河入海口渔港经济的当代活力。','东营',NULL,NULL,'[\"节庆\", \"开渔\", \"东营\", \"渔港\", \"黄河口\"]',0,'published','manual','2026-08-15 11:01:42','2026-08-15 11:01:42',NULL,NULL,NULL,0,0),(65,'festival','中国孙子文化旅游节（广饶）','兵圣故里广饶的年度文旅盛典，金秋时节祭兵圣、论兵学，弘扬“知彼知己”的兵学智慧。','东营广饶为兵圣孙武故里（孙武故里学界考证有争议，广饶说获较多认可，待考）。中国孙子文化旅游节每年9月10日至10月中旬举行，第十七届于2025年9月举办（首届年份据届数推算，待考）。节会设开幕式文艺演出、兵学文化研讨、孙子兵法主题展演与体验、非遗文创市集及文旅经贸活动，弘扬“知彼知己、百战不殆”的兵学智慧与齐地尚武文化。节会依托孙武湖、孙子文化园等载体，将兵圣文化转化为可游可学可体验的文旅产品，是东营最具辨识度的城市文化节庆品牌。','东营',NULL,NULL,'[\"节庆\", \"孙子文化\", \"广饶\", \"东营\", \"兵学\"]',0,'published','manual','2026-08-15 11:01:42','2026-08-15 11:01:42',NULL,NULL,NULL,0,0),(67,'literature','尧的传说（鄄城谷林）','国家级非遗，帝尧葬于鄄城谷林，当地流传尧舜禅让、访贤等传说。','尧的传说流传于山东菏泽鄄城谷林一带。相传帝尧为上古五帝之一，建都平阳，仁德如天，不传子而禅位于舜，被尊为圣王。鄄城谷林传为尧葬之地，谷林尧陵历代祭祀不绝。当地民间世代讲述尧访贤得舜、舜耕历山（鄄城历山古遗址）、尧舜禅让、大禹治水等故事，将上古圣王传说与本地山水风物融为一体。传说彰显公天下、尚贤德的古风，是研究上古史与鲁西南民间信仰的重要口承文献。该项目为国家级非物质文化遗产（申报地区以山西临汾尧都区为主，菏泽鄄城为重要流传地与谷林尧陵所在，名录归属细节待考），堪称齐鲁大地尧舜文化的源头标识之一。','菏泽',NULL,NULL,'[\"尧\", \"舜\", \"鄄城\", \"谷林尧陵\", \"国家级非遗\", \"民间文学\"]',0,'published','manual','2026-08-15 11:04:32','2026-08-15 11:04:32',NULL,NULL,NULL,0,0),(68,'literature','麒麟传说','国家级非遗，巨野为西狩获麟之地，流传麒麟呈祥、获麟绝笔等传说。','麒麟传说流传于山东菏泽巨野一带。麒麟为传说中的仁兽，不践生虫、不折生草，主太平祥瑞。相传春秋鲁哀公十四年，鲁国西狩大野（今巨野）获麟，孔子见麟而叹\'吾道穷矣\'，遂绝笔《春秋》，史称\'获麟绝笔\'。巨野因此被视为麒麟降生之地，现存麒麟台（获麟台）遗址。民间围绕麒麟衍生出麒麟送子、麒麟吐书、麒麟呈祥等故事，婚嫁节庆喜用麒麟图案祈吉纳福。该传说将圣贤文化、祥瑞信仰与地方风物相结合，2008年入选第二批国家级非物质文化遗产名录，是鲁西南最具代表性的民间文学遗产之一。','菏泽',NULL,NULL,'[\"麒麟\", \"获麟绝笔\", \"孔子\", \"巨野\", \"国家级非遗\", \"民间文学\"]',0,'published','manual','2026-08-15 11:04:32','2026-08-15 11:04:32',NULL,NULL,NULL,0,0),(69,'literature','大舜传说','省级非遗，舜耕历山的传说在济南历下区世代流传，千佛山古称历山。','大舜传说流传于济南历下区一带。相传舜为有虞氏，生于诸冯，耕于历山，济南历山即今千佛山，山下有舜井、舜祠、娥英水等遗迹。传说舜在历山耕田，象为之耕、鸟为之耘；在雷泽捕鱼、河滨制陶，所居之处一年成聚、二年成邑。他孝感动天、宽厚待人，终受尧禅让为帝，后人尊其为\'大舜\'。历下区民间世代讲述舜耕历山、孝感动天、娥皇女英等故事，并与趵突泉、舜井等泉城风物相连。传说体现了孝德文化与德政思想，是济南泉城文化的精神源头，现为山东省省级非物质文化遗产代表性项目。','济南',NULL,NULL,'[\"大舜\", \"舜耕历山\", \"千佛山\", \"济南\", \"省级非遗\", \"民间文学\"]',0,'published','manual','2026-08-15 11:04:32','2026-08-15 11:04:32',NULL,NULL,NULL,0,0),(70,'literature','闵子骞传说','省级非遗，闵子骞芦衣顺母的孝道传说在济南历城世代流传。','闵子骞传说流传于济南历城区一带。闵子骞名损，字子骞，孔子弟子，以德行著称。相传他幼年丧母，继母虐待他，寒冬以芦花絮衣，而亲生子以棉絮为衣。其父察觉后欲休弃继母，子骞跪求说：\'母在一子寒，母去三子单。\'父亲感悟，继母亦悔改，全家和好。\'鞭打芦花\'\'芦衣顺母\'的故事由此传为千古孝道典范，被列入《二十四孝》。济南历城存闵子骞墓及闵子祠，历代奉祀不绝。传说倡导以德报怨、以孝化人，是儒家孝道文化在齐鲁民间的生动载体，现为山东省省级非物质文化遗产代表性项目。','济南',NULL,NULL,'[\"闵子骞\", \"二十四孝\", \"芦衣顺母\", \"济南\", \"省级非遗\", \"民间文学\"]',0,'published','manual','2026-08-15 11:04:32','2026-08-15 11:04:32',NULL,NULL,NULL,0,0),(71,'literature','东方朔传说','省级非遗，西汉名臣东方朔的机智传说在德州陵城世代流传。','东方朔传说流传于德州陵城区一带。东方朔，字曼倩，西汉文学家，平原厌次（今德州陵城区）人。相传他博闻多智、诙谐善辩，汉武帝时官至太中大夫，常以嬉笑讽谏规劝君王，留下骂杀侏儒、射覆猜谜、谏阻扩建上林苑等轶事，民间称其\'智圣\'。陵城现存东方朔墓及故里遗址，当地百姓世代讲述他戏弄朝臣、巧解难题的故事，并举办东方朔庙会祭祀纪念。传说将历史人物智慧化、喜剧化，展现了齐地诙谐尚智的民风，是鲁北最具代表性的历史人物传说之一，现为山东省省级非物质文化遗产代表性项目。','德州',NULL,NULL,'[\"东方朔\", \"智圣\", \"陵城\", \"德州\", \"省级非遗\", \"民间文学\"]',0,'published','manual','2026-08-15 11:04:32','2026-08-15 11:04:32',NULL,NULL,NULL,0,0),(72,'literature','四女寺的传说','流传于德州武城四女寺一带的孝道传说，四女侍母终身不嫁。','四女寺的传说流传于德州武城县四女寺镇。相传汉代此地傅氏有女四人，父亡母病，四女矢志侍母，终身不嫁，各植槐树一株以明心志，人称\'四女槐\'。母殁后四女于墓前立祠，乡人感其孝行，建寺奉祀，寺因四女得名。后世四女寺临运河而兴，成为运河沿岸商贸重镇，四女孝亲的故事也随漕运商旅传遍南北，被编为京剧《四女槐》搬上舞台。传说将孝道美德与运河古镇兴衰相系，是鲁西北孝文化的重要口承文本，列入武城县非物质文化遗产名录（名录级别待考）。','德州',NULL,NULL,'[\"四女寺\", \"孝道\", \"武城\", \"德州\", \"运河文化\", \"民间文学\"]',0,'published','manual','2026-08-15 11:04:32','2026-08-15 11:04:32',NULL,NULL,NULL,0,0),(73,'literature','孟姜女传说（淄博）','国家级非遗，孟姜女哭长城的传说在淄博淄川世代流传（与泰安流传版本并存）。','孟姜女传说为中国四大民间传说之一，在淄博淄川区流传尤盛。相传秦时孟姜女与范喜良新婚三日，丈夫即被征修长城，一去不返。孟姜女缝制寒衣千里寻夫，到长城方知丈夫已劳累而死、尸骨填于城墙之内，她悲痛欲绝，连哭数日，竟哭倒长城，露出丈夫尸骨，遂滴血认骨、背负归乡。淄川民间相传孟姜女为本地人，当地存孟姜女庙等相关遗迹（待考）。传说控诉暴政、礼赞忠贞，是齐鲁民间文学的代表性遗产，现为国家级非物质文化遗产代表性项目（淄博为申报/保护地区，入选批次待考）。','淄博',NULL,NULL,'[\"孟姜女\", \"四大传说\", \"淄川\", \"淄博\", \"国家级非遗\", \"民间文学\"]',0,'published','manual','2026-08-15 11:04:32','2026-08-15 11:04:32',NULL,NULL,NULL,0,0),(74,'literature','牛郎织女传说（沂源）','国家级非遗，沂源为牛郎织女传说核心流传地，存织女洞牛郎庙。','牛郎织女传说为中国四大民间传说之一，淄博沂源县为其重要流传地。沂源燕崖镇一带山水相连，织女洞与牛郎官庄隔河相望，传为故事发生地。相传织女下凡与牛郎结为夫妻，男耕女织，育有一双儿女；王母娘娘怒而拔簪划出天河，将二人隔开，只许每年七夕鹊桥相会。沂源民间世代讲述牛郎织女故事，保存织女洞、牛郎庙、天孙泉、银河（沂河）等遗迹，并举办七夕爱情文化节。该传说以鹊桥相会寄托古人对坚贞爱情的向往，2008年与山西和顺等地一同入选第二批国家级非物质文化遗产名录，沂源为中国牛郎织女传说研究中心所在地。','淄博',NULL,NULL,'[\"牛郎织女\", \"七夕\", \"沂源\", \"四大传说\", \"国家级非遗\", \"民间文学\"]',0,'published','manual','2026-08-15 11:04:32','2026-08-15 11:04:32',NULL,NULL,NULL,0,0),(75,'literature','董永传说','国家级非遗，董永卖身葬父遇七仙女的传说在博兴世代流传。','董永传说流传于滨州博兴县一带。相传东汉千乘（今博兴）人董永家贫，父死无钱安葬，遂卖身富家为奴以葬父，孝行感动天庭。七仙女私自下凡，于槐荫树下与董永相遇，请老槐树为媒结为夫妻，同至债主家织锦百匹偿债赎身，百日姻缘期满，仙女升天而去。\'卖身葬父\'\'槐荫为媒\'遂成二十四孝与《天仙配》故事的原型，博兴由此得名\'董永故里\'，存董永墓、董永祠及麻大湖等遗迹，每年举办董永文化艺术节。传说将孝道与爱情理想融为一体，现为国家级非物质文化遗产代表性项目（滨州博兴为保护地区，入选批次待考），是齐鲁孝文化的标志性遗产。','滨州',NULL,NULL,'[\"董永\", \"七仙女\", \"二十四孝\", \"博兴\", \"国家级非遗\", \"民间文学\"]',0,'published','manual','2026-08-15 11:04:32','2026-08-15 11:04:32',NULL,NULL,NULL,0,0),(76,'literature','丈八佛传说','市级非遗，博兴旺国寺丈八佛灵验显圣的传说在当地世代流传。','丈八佛传说流传于滨州博兴县湖滨镇丈八佛村一带。兴国寺内供奉北朝石刻释迦牟尼立像，高约一丈八尺，故名丈八佛。相传石佛凿成后灵验异常，凡遇旱涝兵灾，乡人祈祷辄应；一说石佛夜间显圣，为百姓祛病消灾，故香火不绝，村以佛名。丈八佛历经千年沧桑仍保存完好，现为第七批全国重点文物保护单位。当地百姓围绕石佛讲述其开凿、灵验、护佑一方的故事，逢佛诞日与庙会进香祈福。传说融合佛教信仰与乡土记忆，是鲁北民间信仰文学的代表，列入滨州市级非物质文化遗产名录。','滨州',NULL,NULL,'[\"丈八佛\", \"兴国寺\", \"博兴\", \"市级非遗\", \"民间文学\", \"佛教传说\"]',0,'published','manual','2026-08-15 11:04:32','2026-08-15 11:04:32',NULL,NULL,NULL,0,0),(77,'craft','曹州面塑（面人·曹州面人）','国家级非遗，以面塑牡丹、戏曲人物著称的鲁西南民间面塑艺术。','曹州面塑即\"面人（曹州面人）\"，是国家级非物质文化遗产，流行于菏泽市牡丹区及曹县一带。艺人以小麦面、糯米面调色捏塑，题材多取戏曲人物、神话故事与牡丹花卉，造型古朴、色彩艳丽，尤以面塑牡丹闻名。曹县江米人同属鲁西南面塑脉络，曾亮相黄河流域非遗展并登上国际舞台。当代传承人将面塑与现代文创、研学体验结合，在校园与景区开设传习课堂，让老手艺持续焕发新生。','菏泽',NULL,'/images/cultural/caozhou_dough_art.webp','[\"国家级非遗\", \"菏泽\", \"面塑\", \"传统美术\"]',0,'published','manual','2026-08-15 11:05:02','2026-08-24 21:00:47',NULL,NULL,NULL,0,0),(78,'craft','鲁锦织造技艺','国家级非遗，鄄城、郓城一带以彩色棉线织成的鲁西南老粗布织造技艺。','鲁锦织造技艺是国家级非物质文化遗产，主要流传于菏泽鄄城、郓城等县。鲁锦以纯棉纱为经线、彩色棉纱为纬线，在传统木织机上织出平纹、斜纹与提花图案，纹样多取\"八宝\"\"龙凤\"\"万字\"等吉祥题材，质地厚实、色彩浓烈，俗称\"老粗布\"。当代鲁锦在保持手工织造的同时融入设计创新，发展出服饰、家纺、文创等品类，鄄城等地建有鲁锦文化展示体验中心并开展暑期研学，机杼声声不绝于耳。','菏泽',NULL,'/images/cultural/lu_brocade_weaving.webp','[\"国家级非遗\", \"菏泽\", \"织造\", \"传统技艺\"]',0,'published','manual','2026-08-15 11:05:02','2026-08-24 21:00:47',NULL,NULL,NULL,0,0),(79,'craft','曲阜楷木雕刻（木雕·曲阜楷木雕刻）','国家级非遗，以孔林楷木为材、刀法精细的曲阜传统木雕艺术。','曲阜楷木雕刻是国家级非物质文化遗产，因以曲阜孔林所产楷树（黄连木）为雕刻材料而得名，明清两代曾为贡品。艺人以楷木雕刻孔子像、如意、手杖、镇纸等，刀法圆润细腻，尤其\"楷木如意\"与孔庙祭祀礼仪关系密切。当代传承群体在保留传统题材的同时开发文创摆件，依托\"孔孟之乡\"文旅资源开展传习与研学，曲阜楷木雕刻作品屡获国家级奖项，千年非遗薪火相传。','济宁',NULL,NULL,'[\"国家级非遗\", \"济宁\", \"雕刻\", \"传统美术\"]',0,'published','manual','2026-08-15 11:05:02','2026-08-15 11:05:02',NULL,NULL,NULL,0,0),(80,'craft','嘉祥石雕（石雕·嘉祥石雕）','国家级非遗，依托武氏祠汉画像石传统的济宁嘉祥石雕技艺。','嘉祥石雕是国家级非物质文化遗产，济宁嘉祥县素有\"中国石雕之乡\"之称。嘉祥石刻技艺上承武氏祠汉画像石传统，题材涵盖麒麟、石狮、人物、碑刻等，技法分圆雕、浮雕、透雕、线刻，作品气势雄浑、刀法洗练。当代嘉祥石雕已形成集开采、设计、加工、销售于一体的文化产业集群，嘉祥石雕文化产业园聚集大量艺人，产品远销海内外，并广泛运用于城市雕塑与园林建筑。','济宁',NULL,NULL,'[\"国家级非遗\", \"济宁\", \"雕刻\", \"传统美术\"]',0,'published','manual','2026-08-15 11:05:02','2026-08-15 11:05:02',NULL,NULL,NULL,0,0),(81,'craft','泰山玉雕刻（石雕·泰山玉雕刻）','山东省级非遗，以泰山墨玉、碧玉为材的泰山玉石雕刻技艺。','泰山玉雕刻是山东省第六批省级非物质文化遗产代表性项目。泰山玉产自泰山周边，以墨玉为主，兼有碧玉、翠斑玉，质地温润、黑中透亮。艺人依玉施艺，雕刻泰山风景、平安符、茶具、印章等，尤以\"泰山平安玉\"寓意深得市场青睐。当代泰山玉雕从业者众多，泰安市文化馆等机构持续举办玉雕技艺非遗传承体验活动，泰山张氏玉雕等老字号传承脉络清晰，带动泰安玉石文创产业发展。','泰安',NULL,NULL,'[\"省级非遗\", \"泰安\", \"雕刻\", \"传统美术\"]',0,'published','manual','2026-08-15 11:05:02','2026-08-15 11:05:02',NULL,NULL,NULL,0,0),(82,'craft','肥城桃木雕刻','泰安肥城传统雕刻技艺，\"桃木王\"王来新等艺人以桃木制剑、符、如意。（级别待考）','肥城桃木雕刻是泰安肥城市的传统工艺，依托\"世界最大桃园\"的桃木资源发展壮大。艺人取桃木制作桃木剑、桃符、如意、摆件等，借\"桃木辟邪\"民俗寓意走俏市场，相关\"肥城桃木桃符制作民俗\"已列入非遗名录（级别待考）。当地涌现王来新（人称\"桃木王\"）等知名艺人，桃木工艺品形成规模化产业，建有国内首家专业桃木旅游商品博物馆，并获\"肥城桃木雕刻\"国家地理标志证明商标。','泰安',NULL,NULL,'[\"泰安\", \"肥城\", \"雕刻\", \"桃木工艺\"]',0,'published','manual','2026-08-15 11:05:02','2026-08-15 11:05:02',NULL,NULL,NULL,0,0),(83,'craft','德州黑陶烧制技艺（陶器烧制技艺·德州黑陶烧制技艺）','国家级非遗，以\"黑如漆、明如镜、薄如纸\"著称的德州制陶技艺。','德州黑陶烧制技艺是国家级非物质文化遗产（入选批次待考），流传于德州德城区一带。黑陶以黄河淤积细泥为原料，经练泥、拉坯、修坯、压光、雕刻、烧制而成，成品\"黑如漆、亮如镜、薄如纸、叩如磬\"。梁子黑陶等企业在传统基础上恢复硬刻陶、镂空、浮雕等工艺，并发展彩陶与文创产品，德州学院建有黑陶文化产业学院，形成\"非遗+教育+产业\"的当代传承模式。','德州',NULL,NULL,'[\"国家级非遗\", \"德州\", \"制陶\", \"传统技艺\"]',0,'published','manual','2026-08-15 11:05:02','2026-08-15 11:05:02',NULL,NULL,NULL,0,0),(84,'craft','蟋蟀罐传统制作技艺（宁津）','山东省级非遗，宁津\"中华蟋蟀第一县\"以澄浆泥制蟋蟀罐的技艺。','蟋蟀罐传统制作技艺是山东省省级非物质文化遗产（第五批省级名录，2021），流传于德州宁津县。宁津素有\"中华蟋蟀第一县\"之称，斗蟋之风催生了制罐行业。艺人取黄河澄浆细泥，经澄泥、练泥、拉坯、晾干、烧制等工序制成蟋蟀罐，罐壁致密透气、保湿性好，讲究\"养口\"。宁津蟋蟀罐远销京津沪等地，\"小罐子\"闯出大市场，形成集养殖、用具、赛事于一体的蟋蟀文化产业。','德州',NULL,NULL,'[\"省级非遗\", \"德州\", \"制陶\", \"蟋蟀文化\"]',0,'published','manual','2026-08-15 11:05:02','2026-08-15 11:05:02',NULL,NULL,NULL,0,0),(85,'craft','泥塑（惠民泥塑）','国家级非遗，惠民河南张村\"泥娃娃\"泥塑及火把李庙会民俗。','惠民泥塑是国家级非物质文化遗产（2021年入选，批次待考），以滨州惠民县河南张村最为著名。艺人取黄河胶泥捏塑\"泥娃娃\"，题材有胖娃娃、戏曲人物、飞禽走兽等，彩绘鲜艳、造型憨态可掬，多寓吉祥之意。每年农历二月二火把李庙会，泥娃娃集市延续数百年。当代惠民泥塑走进校园课堂与非遗工坊，\"非遗+艺术\"融合创新，让老手艺持续传承、不遗失。','滨州',NULL,NULL,'[\"国家级非遗\", \"滨州\", \"泥塑\", \"传统美术\"]',0,'published','manual','2026-08-15 11:05:02','2026-08-15 11:05:02',NULL,NULL,NULL,0,0),(86,'craft','柳编（博兴柳编）','国家级非遗，博兴\"草柳编之乡\"以柳条、蒲草编织器具的传统技艺。','博兴柳编是国家级非物质文化遗产（第三批，2011），滨州博兴县为\"中国草柳编之乡\"。当地以柳条、蒲草、玉米皮为原料，编成提篮、箱包、工艺品等，技法有平编、绞编、勒编等数十种，制品柔韧耐用、天然环保。博兴草柳编已形成集种植、加工、电商销售于一体的产业集群，年产值可观、产品远销海外，湾头村等专业村落的\"草柳编一条街\"成为产业与文旅融合的样本。','滨州',NULL,NULL,'[\"国家级非遗\", \"滨州\", \"编织\", \"传统技艺\"]',0,'published','manual','2026-08-15 11:05:03','2026-08-15 11:05:03',NULL,NULL,NULL,0,0),(87,'craft','毛笔制作技艺（广饶齐笔制作技艺）','山东省级非遗，东营广饶\"齐笔\"与湖笔、宣笔齐名的制笔技艺。','广饶齐笔制作技艺是山东省省级非物质文化遗产，流传于东营广饶县大王镇一带。齐笔古称\"齐国笔\"，与浙江湖笔、安徽宣笔等并称名笔，以\"尖、齐、圆、健\"四德著称。制笔选用优质狼毫、羊毫、紫毫，经选料、脱脂、梳理、扎毫、装管、修笔等百余道工序精制而成。当代齐笔依托广饶非遗展览、传承人工作室延续技艺，朱长春等艺人坚守制笔五十余载，齐笔产品远销海内外。','东营',NULL,NULL,'[\"省级非遗\", \"东营\", \"制笔\", \"传统技艺\"]',0,'published','manual','2026-08-15 11:05:03','2026-08-15 11:05:03',NULL,NULL,NULL,0,0),(88,'craft','黄河口芦苇画','东营河口区非遗项目，以黄河口芦苇为材、烙烫成画的工艺。（省级待考）','黄河口芦苇画是东营市河口区的非物质文化遗产代表性项目（市级，省级资格待考）。艺人取黄河入海口天然芦苇，经选料、剖秆、压平、剪贴、烙烫等工序制成画作，题材多取湿地风光、飞禽与民俗吉祥图案，画风自然质朴、富有黄河口地域特色。东营职业学院等院校开展芦苇手工艺活态传承，东营市文化馆开设非遗传习课程，芦苇画还常与生肖主题结合，成为黄河口特色文创与旅游伴手礼。','东营',NULL,NULL,'[\"东营\", \"芦苇画\", \"贴画\", \"黄河口文化\"]',0,'published','manual','2026-08-15 11:05:03','2026-08-15 11:05:03',NULL,NULL,NULL,0,0),(90,'food_opera','甏肉干饭','济宁传统名吃，以陶甏慢火焖肉配米饭，肉烂汤浓、肥而不腻，是运河码头的老味道。','甏肉干饭是济宁最具代表性的传统名吃，因以“甏”（陶制大罐）焖制五花肉而得名。将带皮五花肉改刀入甏，加酱油与八角、桂皮等香料小火慢焖，肉烂汤浓、肥而不腻，配现蒸米饭，佐以卤蛋、面筋、豆腐卷、海带结等配菜，一甏之内滋味丰富。其形成与京杭大运河济宁段漕运码头的饮食传统密切相关（待考），运河船工与码头食肆以甏代锅、连甏带饭的吃法沿袭至今。甏肉干饭已列入济宁市非遗展播项目，多家老字号品牌化经营，成为“老济宁”记忆里的运河美食名片。','济宁',NULL,'/images/cultural/bengrou_rice.webp','[\"济宁\", \"运河美食\", \"地方小吃\", \"传统名吃\"]',0,'published','manual','2026-08-15 11:05:33','2026-08-24 21:00:47',NULL,NULL,NULL,0,0),(91,'food_opera','四平调（金乡四平调）','发源于济宁金乡的国家级非遗戏曲，由民间花鼓演变而来，唱腔质朴、乡土气息浓。','四平调是流行于鲁西南、豫东、苏北、皖北交界地带的地方戏曲剧种，济宁金乡为其重要发源地与流传中心之一。四平调由民间“花鼓”（花鼓丁香）说唱演变而来，唱腔以平腔为主，四句一循环、平稳舒展，故名“四平调”，板式有慢板、二八板等，表演载歌载舞、生活气息浓厚。金乡县四平调剧团长期活跃于乡村舞台，传承有序。2008年，四平调入选第二批国家级非物质文化遗产名录（编号Ⅳ-50，申报地区含金乡县、成武县）。金乡持续开展非遗进校园与展演活动，传统剧目《刘芳福借银》等仍在传演。','济宁',NULL,NULL,'[\"济宁\", \"金乡\", \"地方戏曲\", \"国家级非遗\"]',0,'published','manual','2026-08-15 11:05:33','2026-08-15 11:05:33',NULL,NULL,NULL,0,0),(92,'food_opera','泰山豆腐宴','泰安市级非遗，以泰山豆腐为主料、泰山泉水点化的传统宴席，菜品多达百余道。','泰山豆腐宴是以泰山豆腐为主料形成的传统宴席，与泰山“三美”（白菜、豆腐、水）一脉相承，讲究用泰山泉水点浆、配泰山白菜与时蔬。相传与历代帝王泰山封禅祭祀的素食传统有关（待考），民间有“豆腐满汉全席”之称，菜品多达百余道，煎、炒、炖、炸、蒸俱全，代表作如“泰山三美”锅仔、八宝豆腐等。2012年前后，泰山豆腐宴入选泰安市非物质文化遗产名录。如今豆腐宴从“皇家御膳”走向百姓餐桌，泰安多家餐饮老店将其列为招牌，成为泰山旅游的饮食名片。','泰安',NULL,NULL,'[\"泰安\", \"泰山\", \"传统宴席\", \"市级非遗\"]',0,'published','manual','2026-08-15 11:05:33','2026-08-15 11:05:33',NULL,NULL,NULL,0,0),(93,'food_opera','山东梆子（泰安）','国家级非遗剧种，泰安设专业剧院，唱腔高亢激越，是山东梆子腔系重要代表。','山东梆子又称“高调梆子”，是流行于鲁西南、鲁中及豫冀苏皖部分地区的古老梆子腔剧种，泰安是其重要流行区之一。山东梆子相传由山陕梆子东传后与山东语音、民间音乐融合而成（待考），唱腔高亢激越、慷慨激昂，板式丰富，表演质朴火爆。泰安市山东梆子剧院（原泰安市山东梆子剧团）坚守传承数十年，复排《两狼山上》等传统剧目并冲击文华奖，在宁阳等地开展“老戏新唱”。2008年，山东梆子入选第二批国家级非物质文化遗产名录，成为山东梆子腔系的重要代表。','泰安',NULL,NULL,'[\"泰安\", \"山东梆子\", \"地方戏曲\", \"国家级非遗\"]',0,'published','manual','2026-08-15 11:05:33','2026-08-15 11:05:33',NULL,NULL,NULL,0,0),(94,'food_opera','临清什香面','临清运河名吃，手擀面配十余种菜码，一面百味，制作技艺入选省级非遗。','临清什香面是聊城临清的传统名吃，因配料繁多的“什锦”菜码得名。手擀面条细韧筋道，配以黄瓜丝、豆芽、香椿芽、咸香椿、蒜薹、腌萝卜、芝麻盐、麻汁及多种酱料等十余种菜码，吃时现拌，一碗面中尝尽百味。临清地处京杭大运河要冲，漕运商贸繁荣，什香面融合南北饮食之长，是运河饮食文化的活标本。临清什香面制作技艺已入选山东省级非物质文化遗产项目，央视等媒体多次报道，成为“运河美食”的代表之一。','聊城',NULL,NULL,'[\"聊城\", \"临清\", \"运河美食\", \"省级非遗\"]',0,'published','manual','2026-08-15 11:05:33','2026-08-15 11:05:33',NULL,NULL,NULL,0,0),(95,'food_opera','聊城八角鼓','聊城曲艺类省级非遗，满族八角鼓与运河方言融合的说唱艺术，百年传承。','聊城八角鼓是流传于聊城（东昌府、临清一带）的说唱曲艺，源于清代满族八角鼓曲艺，随旗人驻防与运河商路传入鲁西，与当地方言、民间音乐融合而成（待考）。表演以八角鼓（八边形单面鼓）击节，间以三弦等伴奏，说唱结合、语言风趣，书目多取材于民间传说与市井故事。20世纪中叶曾盛极一时，后一度濒临失传，被媒体称为“大运河畔失落的遗韵”。近年已列入山东省非物质文化遗产名录，东昌府区组织八角鼓艺术团展演、开展非遗进校园，老曲种正焕发新声。','聊城',NULL,NULL,'[\"聊城\", \"东昌府\", \"曲艺\", \"省级非遗\"]',0,'published','manual','2026-08-15 11:05:33','2026-08-15 11:05:33',NULL,NULL,NULL,0,0),(96,'food_opera','滨州锅子饼','滨州传统名吃，薄饼裹炒馅再烙制，香而不腻、酥而不硬，市级非遗。','滨州锅子饼是滨州最具代表性的传统名吃之一。将面团擀成薄饼在鏊子上烙至半熟，卷入以鸡蛋、豆腐、粉条、韭菜、豆芽等炒制的馅料，再入饼铛（锅子）复烙至金黄，切段食用，外皮酥脆、馅料鲜香，“香而不腻、酥而不硬”。锅子饼馅料可随季节变换，素有“可裹卷万物”之说，无棣佘家等地传承尤盛。滨州锅子饼制作技艺已列入市级非物质文化遗产名录，多家老字号坚守古法，成为滨州待客的招牌名吃。','滨州',NULL,NULL,'[\"滨州\", \"无棣\", \"地方小吃\", \"市级非遗\"]',0,'published','manual','2026-08-15 11:05:33','2026-08-15 11:05:33',NULL,NULL,NULL,0,0),(97,'food_opera','沾化渔鼓戏','滨州沾化国家级非遗，渔鼓击节伴唱的说唱戏曲，独创剧种，相传传承三百年。','沾化渔鼓戏是流行于滨州沾化的地方戏曲剧种，因以渔鼓（竹筒蒙皮）击节伴唱得名，属道情腔系，是滨州独有的地方剧种。相传起源于清雍正年间（约1723年），由渔鼓道情说唱发展而来，唱腔质朴明快，表演载歌载舞，唱词有“三句一番”的结构特点。沾化渔鼓戏以“道情戏（沾化渔鼓戏）”之名列入国家级非物质文化遗产名录；沾化区渔鼓戏剧团坚持创演，推出《老邪上任》《戏说西游·高老庄》等新剧目，走出一条“剧种与剧团互救共赢”的传承之路。','滨州',NULL,NULL,'[\"滨州\", \"沾化\", \"地方戏曲\", \"国家级非遗\"]',0,'published','manual','2026-08-15 11:05:33','2026-08-15 11:05:33',NULL,NULL,NULL,0,0);
