LOCK TABLES `event` WRITE;
/*!40000 ALTER TABLE `event` DISABLE KEYS */;
INSERT INTO `event` VALUES (1,'李杜齐鲁相会','天宝三载（744年）至天宝四载（745年），\"诗仙\"李白与\"诗圣\"杜甫在洛阳相识后，同游梁宋（今河南开封、商丘），并先后两次来到山东齐鲁大地。他们同游济南大明湖、泰山、泗水等地，携手登高、饮酒赋诗，度过了一段真挚的文学交游时光。最终在曲阜东石门山依依惜别。',4,745,'中国文学史上最伟大的双子星的相遇与同游，代表了盛唐气象下文人交往的巅峰，留下了《鲁郡东石门送杜二甫》、《陪李北海宴历下亭》等传世名篇，对山东段黄河流域的文学地标构建具有奠基性意义。','https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/events/lidu_meeting.jpg','2026-07-01 20:38:18','2026-08-20 22:01:45',0),(2,'赵孟頫出任济南总管','元世祖至元二十九年（1292年），著名书画家赵孟頫出任同知济南路总管府事。在任三年期间，他深入考察济南的山川泉水，写下了《趵突泉》等描绘泉城风光的诗歌。并在离任后根据记忆绘制了中国艺术史上著名的《鹊华秋色图》，展现济南鹊山和华不注山一带的清丽风光。',6,1292,'极大地提升了济南泉水与山水在全国文学艺术界的地位，其创作的《鹊华秋色图》和诗歌成为济南最具标志性的艺术文化名片之一。','https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/events/zhao_jinan.jpg','2026-07-01 20:38:18','2026-08-20 22:01:45',0),(3,'蒲松龄柳泉设茶采风','清康熙年间，蒲松龄在故乡淄川（今淄博市淄川区）的柳泉（又称满井）旁设立茅亭，为过往行人免费提供茶水，只求路人讲述听闻的民间怪异故事或传说。他以此积累了大量的创作素材，并在其\"聊斋\"中挑灯夜战，历时数十年创作出中国文言小说巅峰之作《聊斋志异》。',8,1679,'开启了中国古典文学史上独特的\"民间采风\"与\"文人再创作\"模式，使淄博柳泉成为聊斋文化的核心发源地，构建了极具鲁中特色的神秘浪漫文学景观。','https://shandong-lit-landscape.oss-cn-beijing.aliyuncs.com/events/pu_gathering.jpg','2026-07-01 20:38:18','2026-08-20 22:01:45',0);
/*!40000 ALTER TABLE `event` ENABLE KEYS */;
UNLOCK TABLES;

