  `item_id` bigint NOT NULL,
  `festival_date` varchar(100) DEFAULT NULL COMMENT '节庆时间（如"农历正月初一""每年4月"）',
  `origin` text COMMENT '起源渊源',
  `customs` text COMMENT '习俗活动',
  `food` text COMMENT '节庆饮食',
  PRIMARY KEY (`item_id`),
  CONSTRAINT `festival_detail_ibfk_1` FOREIGN KEY (`item_id`) REFERENCES `cultural_item` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='民俗节庆扩展表';
