LOCK TABLES `festival_detail` WRITE;
/*!40000 ALTER TABLE `festival_detail` DISABLE KEYS */;
INSERT INTO `festival_detail` VALUES (52,'每年4月中下旬至5月初（牡丹盛花期）','源于曹州（今菏泽）千年牡丹栽培传统，明清时牡丹已成曹州名品；1992年举办首届菏泽国际牡丹花会，延续至今。','赏花游园、牡丹摄影与书画笔会、戏曲及非遗展演、牡丹产品与文创市集','牡丹宴（以牡丹入馔）及牡丹花茶、牡丹糕点等（具体席面待考）'),(53,'每年9月28日（孔子诞辰纪念日）','始于孔子卒后第二年的家祭，历代帝王尊崇祀孔，明清形成国家层面的释奠礼制；当代恢复公祭后每年于孔子诞辰日举行。','迎神、三献礼、佾舞雅乐、诵读《论语》、海内外文庙联动公祭',''),(54,'农历三月二十八前后（当代多于4月中下旬启会）','源于泰山崇拜与东岳大帝信仰，唐宋年间随香火兴盛形成庙会，明清鼎盛，传承至今。','朝山进香、祭祀祈福、民间杂技戏曲展演、非遗市集、商贸集会','泰山煎饼、豆腐脑等庙会小吃（具体摊档待考）'),(55,'每年春节期间（正月；传统会期因庙宇而异，待考）','源于明清漕运商埠的祭祀与商贸集会传统，清代临清庙会众多，随运河兴衰而变迁。','进香祈福、社火巡游、驾鼓表演、戏曲曲艺演出、非遗展示与商贸集市','临清什香面等运河风味小吃（待考）'),(56,'春节、庙会及重大节庆期间展演','源于古代军旅仪仗锣鼓，随运河商埠庙会社火传承，明清至近现代不绝（具体形成年代待考）。','驾鼓列阵巡演、社火踩街、庙会助兴、节庆庆典展演',''),(57,'每年春节期间（腊月下旬至正月十五前后）','承济南上元赏灯古俗；现代灯会始于1965年，由趵突泉公园举办，历届不辍。','赏灯游园、猜灯谜、民俗演出、非遗手作展示、夜游泉水','元宵、糖葫芦等年节小吃'),(58,'每年农历九月初九（重阳节）前后','承古代重阳登高习俗与千佛山祭祀传统，历史已延续七百余年。','登高祈福、赏菊、庙会集市、民俗杂技展演、敬老活动','糖炒栗子、糖葫芦等山会小吃（待考）'),(59,'每年9月（枣熟时节）','承乐陵枣乡种植传统与枣文化民俗；1989年举办首届金丝小枣节，延续至今。','枣园采摘、枣乡民俗展演、红枣品鉴与产业博览、文旅市集','乐陵金丝小枣、枣糕等枣制食品'),(60,'每年秋季（9—10月，逐年浮动，待考）','承宁津斗蟋民俗与杂技之乡传统；2010年代创办蟋蟀文化节，2024年增设杂技古会。','斗蟋观战、蟋蟀交易、杂技展演、古会市集、非遗美食体验','宁津保店驴肉等地方名吃（待考）'),(61,'每年9月（通常9月12日前后开幕）','为纪念齐国故都与姜太公、齐桓公等历史人物、弘扬齐文化而设，2004年创办。','开幕式文艺演出、祭祀姜太公仪式（待考）、蹴鞠展演、齐文化论坛、非遗文创市集',''),(62,'每年“五一”假期前后（4月底至5月初）','依托蒲松龄故里与聊斋文化资源创办于21世纪初，历年以五一假期为节期。','聊斋园游览、奇幻演艺、民俗市集、非遗体验、文创展销',''),(63,'每年农历正月十二至十六前后','相传源于元代说书艺人年节聚会（待考），明清成俗，历代相沿，今仍为全国性曲艺盛会。','曲艺说书、曲艺擂台赛、非遗展演、民俗市集、文旅经贸活动',''),(64,'每年9月初（黄渤海开海前后）','承渔民开海祭海传统；2017年首届开渔节于垦利红光渔港举办，延续至今。','开海仪式、千帆出海、祭海祈福（待考）、海鲜美食节、渔港市集','梭子蟹、开凌梭鱼等“开海第一鲜”'),(65,'每年9月10日至10月中旬','依托广饶孙武故里文化资源创办于21世纪初（首届年份待考），为弘扬孙子兵学文化而设。','开幕式演出、兵学研讨、兵法主题体验、非遗市集、文旅经贸活动','');
/*!40000 ALTER TABLE `festival_detail` ENABLE KEYS */;
UNLOCK TABLES;

