INSERT INTO `food_opera_detail` VALUES (45,'food','鲁菜','海鲜、禽畜、蔬菜、豆制品、面食','爆、炒、烧、塌、焖、扒、溜、炸、烩等','糖醋鲤鱼、九转大肠、葱烧海参、油焖大虾、德州扒鸡','鲁菜起源于春秋战国时期，历经秦汉、隋唐、明清不断发展完善','鲁菜作为中国八大菜系之首，在国内外享有盛誉','国家级非物质文化遗产'),(46,'food','鲁菜','整鸡、香料（八角、桂皮、丁香、砂仁等）、酱油、盐','宰杀、整形、油炸、卤煮、焖制','德州扒鸡','德州扒鸡始于明代，相传乾隆皇帝南巡时曾品尝并赞誉','德州扒鸡已成为中国驰名商标，远销国内外','国家级非物质文化遗产'),(47,'food','鲁点','面粉、芝麻、糖、盐、花生油','和面、揉剂、成型、烘烤','周村烧饼','周村烧饼起源于汉代，明清时期成为贡品','周村烧饼已成为中国驰名商标，远销国内外','省级非物质文化遗产'),(48,'food','鲁菜','小米、玉米、高粱等杂粮、大葱、酱料','磨面、摊制、卷料、蘸酱','煎饼卷大葱','山东煎饼历史悠久，相传孟姜女哭长城时带的就是煎饼','煎饼卷大葱是山东人民日常主食，深受喜爱','市级非物质文化遗产'),(49,'opera','吕剧','演员、乐队（坠琴、扬琴、二胡等）、服装道具','唱、念、做、打，以唱为主','《李二嫂改嫁》《姊妹易嫁》《小姑贤》','吕剧起源于清代末年，由山东琴书发展而来','吕剧是国家级非物质文化遗产，在山东各地广泛流传','国家级非物质文化遗产'),(50,'opera','山东快书','表演者、竹板、服装','说、唱、表演，以说为主','《武松传》《鲁达除霸》《马寡妇开店》','山东快书起源于清代，由民间说唱艺术发展而来','山东快书是国家级非物质文化遗产，在山东各地广泛流传','国家级非物质文化遗产'),(51,'opera','柳子戏','演员、乐队（柳琴、笛子、唢呐等）、服装道具','唱、念、做、打，以唱为主','《白兔记》《金锁记》《孙安动本》','柳子戏起源于明代，由民间小调发展而来','柳子戏是国家级非物质文化遗产，在菏泽等地流传','国家级非物质文化遗产'),(90,'food','鲁菜（济宁地方风味）','带皮五花肉、酱油、八角、桂皮等香料、米饭、卤蛋、面筋、豆腐卷、海带结','五花肉改刀入甏，加酱油香料小火慢焖，配菜卤制，米饭现蒸','甏肉干饭（甏肉、卤蛋、面筋、豆腐卷等）','与京杭大运河济宁段漕运码头饮食传统密切相关，具体起始年代无确考（待考）','列入济宁市非遗展播项目，多家老字号品牌化经营，为济宁运河美食名片','市级非遗(待考)'),(91,'opera','四平调（地方戏曲）','演员（生旦净丑行当）、乐队（板胡、二胡、笛子、打击乐等）、服装道具','唱、念、做、打并举，以唱为主，四句一循环的平腔板式','《刘芳福借银》等传统剧目','由民间花鼓说唱演变而来，金乡为重要发源地之一，具体成形年代待考','金乡县四平调剧团演出活跃，非遗进校园，传承有序','国家级非遗'),(92,'food','鲁菜（泰安素食风味）','泰山豆腐、泰山泉水、白菜、时蔬、豆制品、调味料','泉水点浆制豆腐，煎炒炖炸蒸等多种技法成宴','泰山三美、八宝豆腐、豆腐宴全席（百余道菜品）','相传源于泰山封禅祭祀的素食传统（待考），泰山豆腐历史久远，素食文化一脉相承','泰安市非遗，餐饮老店推广，成为泰山旅游饮食名片','市级非遗'),(93,'opera','山东梆子（梆子腔系）','演员（生旦净丑行当）、乐队（板胡、笛子、笙、打击乐等）、服装道具','唱、念、做、打并举，高亢激越的梆子腔板式','《两狼山上》《两狼山》等传统剧目','相传由山陕梆子东传与山东方言融合形成（待考），泰安传唱已久，剧院始建于20世纪50年代（待考）','泰安市山东梆子剧院活跃，复排经典剧目，非遗展演不断','国家级非遗'),(94,'food','鲁菜（临清面食）','面粉、黄瓜丝、豆芽、香椿芽、蒜薹、腌萝卜、芝麻盐、麻汁、多种酱料','和面擀面、煮面过水，十余种菜码分别备制，现拌现食','临清什香面（什锦菜码面）','与运河漕运商贸繁荣及南北饮食融合密切相关，具体起源年代待考','入选省级非遗，央视报道，为临清“运河美食”名片','省级非遗'),(95,'opera','聊城八角鼓（说唱曲艺）','演员（说唱艺人）、八角鼓、三弦等伴奏乐器、醒木等道具','击八角鼓说唱，说唱结合，韵白相间','传统书目多取材于民间传说、市井故事（具体曲目待考）','源于满族八角鼓，清代经运河商路传入聊城（待考）','列入省级非遗名录，东昌府区艺术团展演、非遗进校园','省级非遗'),(96,'food','鲁菜（滨州地方风味）','面粉、鸡蛋、豆腐、粉条、韭菜、豆芽等时令菜蔬','和面擀饼、鏊子烙制、炒馅、卷馅、锅子复烙、切段','滨州锅子饼（素馅/荤素馅）','滨州地区传统名吃，具体起源年代待考，无棣佘家等传承谱系清晰','列入市级非遗名录，老字号经营，为滨州名吃名片','市级非遗'),(97,'opera','渔鼓戏（道情腔系）','演员（生旦净丑行当）、渔鼓、简板、坠琴等乐器、服装道具','击渔鼓伴唱，唱念做舞并重，“三句一番”唱腔结构','《老邪上任》《戏说西游·高老庄》等','相传起源于清雍正年间（约1723年），由渔鼓道情说唱发展而来','国家级非遗，沾化渔鼓戏剧团活跃，新剧目屡获好评','国家级非遗');
/*!40000 ALTER TABLE `food_opera_detail` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `literature_detail`
--

DROP TABLE IF EXISTS `literature_detail`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `literature_detail` (
  `item_id` bigint NOT NULL COMMENT '文化条目ID',
  `genre` varchar(50) DEFAULT NULL COMMENT '体裁: 传说/故事/歌谣/谚语等',
  `origin_region` varchar(100) DEFAULT NULL COMMENT '流传地区',
  `main_characters` text COMMENT '主要人物',
  `plot_summary` text COMMENT '故事梗概',
  `cultural_significance` text COMMENT '文化价值',
  `related_scenic_spots` json DEFAULT NULL COMMENT '关联景点ID数组',
  `collection_source` varchar(200) DEFAULT NULL COMMENT '采集来源',
  PRIMARY KEY (`item_id`),
  KEY `idx_literature_genre` (`genre`),
  KEY `idx_literature_region` (`origin_region`),
  CONSTRAINT `literature_detail_ibfk_1` FOREIGN KEY (`item_id`) REFERENCES `cultural_item` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='民间文学扩展表';
/*!40101 SET character_set_client = @saved_cs_client */;

